<?php

declare(strict_types=1);

namespace Eudr\Tests\Unit\Http\Middleware;

use Eudr\Config\Config;
use Eudr\Config\Credentials;
use Eudr\Data\Commodity;
use Eudr\Data\Producer;
use Eudr\Enums\ActivityType;
use Eudr\Enums\OperatorType;
use Eudr\Requests\V2\SubmitDdsRequest;
use Eudr\Tests\TestCase;

/**
 * Tests the WS-Security header generated by AbstractRequest::addSecurityHeader().
 *
 * This covers the password-digest computation, the WS-Security XML structure
 * (UsernameToken, Nonce, Timestamp), and the WebServiceClientId header.
 * There is no standalone AuthMiddleware class; authentication is handled
 * directly inside the SOAP XML builder.
 */
final class SecurityHeaderTest extends TestCase
{
    public function testSecurityHeaderContainsPasswordDigest(): void
    {
        $config = new Config(
            baseUrl: 'https://example.com',
            credentials: new Credentials('testuser', 'myauthkey', 'myclientid'),
        );

        $request = SubmitDdsRequest::make()
            ->withOperatorType(OperatorType::OPERATOR)
            ->withActivityType(ActivityType::IMPORT)
            ->addCommodity(new Commodity(
                position: 1,
                description: 'Test',
                hsHeading: '4403',
                producers: [new Producer('DE', 'geojson')],
            ));

        $xml = $request->toSoapXml($config);

        // Verify structure of WS-Security header
        $this->assertStringContainsString('wsse:Security', $xml);
        $this->assertStringContainsString('wsu:Timestamp', $xml);
        $this->assertStringContainsString('wsse:UsernameToken', $xml);
        $this->assertStringContainsString('<wsse:Username>testuser</wsse:Username>', $xml);

        // Password should be base64 encoded digest
        $doc = new \DOMDocument();
        $doc->loadXML($xml);
        $xpath = new \DOMXPath($doc);
        $xpath->registerNamespace(
            'wsse',
            'http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd',
        );

        $passwordNodes = $xpath->query('//wsse:Password');
        $this->assertNotNull($passwordNodes);
        $this->assertGreaterThan(0, $passwordNodes->length);

        $passwordNode = $passwordNodes->item(0);
        $this->assertNotNull($passwordNode);
        $this->assertInstanceOf(\DOMElement::class, $passwordNode);

        // Verify the Password Type attribute
        $type = $passwordNode->getAttribute('Type');
        $this->assertSame(
            'http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-username-token-profile-1.0#PasswordDigest',
            $type,
        );

        // Verify Nonce EncodingType
        $nonceNodes = $xpath->query('//wsse:Nonce');
        $this->assertNotNull($nonceNodes);
        $this->assertGreaterThan(0, $nonceNodes->length);

        $nonceNode = $nonceNodes->item(0);
        $this->assertNotNull($nonceNode);
        $this->assertInstanceOf(\DOMElement::class, $nonceNode);

        $encoding = $nonceNode->getAttribute('EncodingType');
        $this->assertSame(
            'http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-soap-message-security-1.0#Base64Binary',
            $encoding,
        );
    }

    public function testPasswordDigestAlgorithm(): void
    {
        // Build a real SOAP request and verify the digest embedded in the XML
        $authKey = 'myauthkey';
        $config = new Config(
            baseUrl: 'https://example.com',
            credentials: new Credentials('testuser', $authKey, 'myclientid'),
        );

        $request = \Eudr\Requests\EchoRequest::make('digest-test');
        $xml = $request->toSoapXml($config);

        // Parse the XML to extract nonce, created, and password digest
        $doc = new \DOMDocument();
        $doc->loadXML($xml);
        $xpath = new \DOMXPath($doc);
        $xpath->registerNamespace(
            'wsse',
            'http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd',
        );
        $xpath->registerNamespace(
            'wsu',
            'http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-utility-1.0.xsd',
        );

        $nonceNode = $xpath->query('//wsse:Nonce')->item(0);
        $this->assertNotNull($nonceNode);
        $nonceBase64 = $nonceNode->textContent;

        $createdNode = $xpath->query('//wsu:Created')->item(0);
        $this->assertNotNull($createdNode);
        $created = $createdNode->textContent;

        $passwordNode = $xpath->query('//wsse:Password')->item(0);
        $this->assertNotNull($passwordNode);
        $actualDigest = $passwordNode->textContent;

        // Independently compute the expected digest: base64(sha1(nonce_bytes + created + authKey))
        $nonceBytes = base64_decode($nonceBase64, true);
        $this->assertNotFalse($nonceBytes);

        $expectedDigest = base64_encode(sha1($nonceBytes . $created . $authKey, true));

        $this->assertSame($expectedDigest, $actualDigest);
    }

    public function testWebServiceClientIdInHeader(): void
    {
        $config = new Config(
            baseUrl: 'https://example.com',
            credentials: new Credentials('user', 'key', 'my-ws-client-id'),
        );

        $request = SubmitDdsRequest::make()
            ->withOperatorType(OperatorType::OPERATOR)
            ->withActivityType(ActivityType::IMPORT)
            ->addCommodity(new Commodity(
                position: 1,
                description: 'Test',
                hsHeading: '4403',
                producers: [new Producer('DE', 'geojson')],
            ));

        $xml = $request->toSoapXml($config);

        $this->assertStringContainsString('WebServiceClientId', $xml);
        $this->assertStringContainsString('my-ws-client-id', $xml);
    }
}
